er{text-align:center;color:#48657d;font-size:10px;padding:20px}@media(max-width:760px){.top{height:62px}.inner,.wrap{padding-left:14px;padding-right:14px}.brand small,.user span{display:none}.user a{font-size:10px;padding:7px}.welcome{padding:21px 18px}.welcome h1{font-size:23px}.stats{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.row{align-items:flex-start}.manage{flex-direction:column;align-items:flex-end}.actions{grid-template-columns:1fr 1fr}}</style></head><body><header class="top"><div class="inner"><a class="brand" href="/client"><span class="logo">N</span><span>Nodexa<small>HOSTING CLOUD</small></span></a><div class="user"><span>{{$user->email}}</span><a href="/store">Bestil</a><a href="/account">Min konto</a><a href="/">Serverpanel</a></div></div></header>@if(session('success'))<div class="alert">{{session('success')}}</div>@endif<main class="wrap"><section class="welcome"><span class="eyebrow">Nodexa Client Control</span><h1>Godt at se dig, {{$user->username??$user->email}}.</h1><p>Administrér hosting, VPS'er, fakturaer og support fra ét samlet kontrolpanel.</p></section><section class="stats"><div class="stat"><strong>{{$services->count()}}</strong><span>Game servers</span></div><div class="stat"><strong>{{$vpsServices->count()}}</strong><span>VPS'er</span></div><div class="stat"><strong>{{$invoices->where('status','unpaid')->count()}}</strong><span>Ubetalte fakturaer</span></div><div class="stat"><strong>{{$tickets->where('status','!=','closed')->count()}}</strong><span>Åbne tickets</span></div></section><div class="grid"><div><section class="card"><div class="title">Mine game servers <small>{{$services->count()}} servere</small></div>@forelse($services as $s)<div class="row"><div><strong>{{$s->name??('Server #'.$s->id)}}</strong><div class="small">Game Server · #{{$s->id}}</div></div><a class="btn" href="/">Administrér</a></div>@empty<div class="empty">Ingen game servers på kontoen.<br><br><a class="btn" href="/store/games">Bestil game 